//! Ordered root-frame symbols for the Jinja-compatible frontend.
//!
//! This planner records lookup and initialization requirements only. It does
//! not yet change generated bytecode or runtime name resolution.
use std::collections::HashSet;

use crate::compiler::ast;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RootLoadKind {
    Resolve,
    Missing,
    SelfReference,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct RootSymbol<'a> {
    pub name: &'a str,
    pub load: RootLoadKind,
}

#[derive(Clone, Default)]
struct Symbols<'a> {
    entries: Vec<RootSymbol<'a>>,
    stores: HashSet<&'a str>,
}

impl<'a> Symbols<'a> {
    fn position(&self, name: &str) -> Option<usize> {
        self.entries.iter().position(|entry| entry.name == name)
    }

    fn load(&mut self, name: &'a str) {
        if self.position(name).is_none() {
            self.entries.push(RootSymbol { name, load: RootLoadKind::Resolve });
        }
    }

    fn store(&mut self, name: &'a str) {
        self.stores.insert(name);
        if self.position(name).is_none() {
            self.entries.push(RootSymbol { name, load: RootLoadKind::Missing });
        }
    }

    fn merge_branches(&mut self, branches: &[Symbols<'a>]) {
        let prior_stores = self.stores.clone();
        let mut branch_stores = HashSet::new();
        for branch in branches {
            branch_stores.extend(branch.stores.iter().copied());
            for entry in &branch.entries {
                if let Some(index) = self.position(entry.name) {
                    self.entries[index].load = entry.load;
                } else {
                    self.entries.push(*entry);
                }
            }
            self.stores.extend(branch.stores.iter().copied());
        }
        for name in branch_stores.difference(&prior_stores) {
            if let Some(index) = self.position(name) {
                self.entries[index].load = RootLoadKind::Resolve;
            }
        }
    }

    fn args(&mut self, args: &[ast::CallArg<'a>]) {
        for category in 0..4 {
            for arg in args {
                let expr = match (category, arg) {
                    (0, ast::CallArg::Pos(expr)) | (1, ast::CallArg::Kwarg(_, expr))
                    | (2, ast::CallArg::PosSplat(expr)) | (3, ast::CallArg::KwargSplat(expr)) => expr,
                    _ => continue,
                };
                self.expr(expr);
            }
        }
    }

    fn call(&mut self, call: &ast::Call<'a>) {
        self.expr(&call.expr);
        self.args(&call.args);
    }

    fn expr(&mut self, expr: &ast::Expr<'a>) {
        match expr {
            ast::Expr::Var(node) => self.load(node.id),
            ast::Expr::Const(_) => {}
            ast::Expr::UnaryOp(node) => self.expr(&node.expr),
            ast::Expr::BinOp(node) => { self.expr(&node.left); self.expr(&node.right); }
            ast::Expr::Concat(node) => for expr in &node.values { self.expr(expr); },
            ast::Expr::Compare(node) => {
                self.expr(&node.expr);
                for op in &node.ops { self.expr(&op.expr); }
            }
            ast::Expr::IfExpr(node) => {
                self.expr(&node.test_expr);
                self.expr(&node.true_expr);
                if let Some(expr) = &node.false_expr { self.expr(expr); }
            }
            ast::Expr::Filter(node) => {
                if let Some(expr) = &node.expr { self.expr(expr); }
                self.args(&node.args);
            }
            ast::Expr::Test(node) => { self.expr(&node.expr); self.args(&node.args); }
            ast::Expr::GetAttr(node) => self.expr(&node.expr),
            ast::Expr::GetItem(node) => { self.expr(&node.expr); self.expr(&node.subscript_expr); }
            ast::Expr::Slice(node) => {
                self.expr(&node.expr);
                for expr in [&node.start, &node.stop, &node.step].into_iter().flatten() { self.expr(expr); }
            }
            ast::Expr::Call(node) => self.call(node),
            ast::Expr::List(node) => for expr in &node.items { self.expr(expr); },
            ast::Expr::Map(node) => for (key, value) in node.keys.iter().zip(&node.values) {
                self.expr(key);
                self.expr(value);
            },
        }
    }

    fn target(&mut self, target: &ast::Expr<'a>) {
        match target {
            ast::Expr::Var(node) => self.store(node.id),
            ast::Expr::List(node) => for item in &node.items { self.target(item); },
            // Namespace assignment reads its receiver, not a new local name.
            ast::Expr::GetAttr(node) => self.expr(&node.expr),
            ast::Expr::GetItem(node) => { self.expr(&node.expr); self.expr(&node.subscript_expr); }
            _ => {}
        }
    }

    fn statements(&mut self, nodes: &[ast::Stmt<'a>]) {
        for node in nodes { self.stmt(node); }
    }

    fn stmt(&mut self, node: &ast::Stmt<'a>) {
        match node {
            ast::Stmt::Template(node) => self.statements(&node.children),
            ast::Stmt::EmitExpr(node) => self.expr(&node.expr),
            ast::Stmt::EmitRaw(_) => {}
            // A loop body, its filter and else have separate Jinja frames.
            ast::Stmt::ForLoop(node) => self.expr(&node.iter),
            ast::Stmt::IfCond(node) => {
                self.expr(&node.expr);
                let mut yes = self.clone();
                yes.statements(&node.true_body);
                let mut no = self.clone();
                no.statements(&node.false_body);
                self.merge_branches(&[yes, no]);
            }
            ast::Stmt::WithBlock(node) => for (_, value) in &node.assignments { self.expr(value); },
            ast::Stmt::Set(node) => { self.expr(&node.expr); self.target(&node.target); }
            ast::Stmt::SetBlock(node) => self.target(&node.target),
            // Autoescape creates a separate scoped frame in Jinja.
            ast::Stmt::AutoEscape(_) => {}
            ast::Stmt::FilterBlock(node) => self.expr(&node.filter),
            #[cfg(feature = "multi_template")]
            ast::Stmt::Block(_) => {}
            #[cfg(feature = "multi_template")]
            ast::Stmt::Extends(node) => self.expr(&node.name),
            #[cfg(feature = "multi_template")]
            ast::Stmt::Include(node) => self.expr(&node.name),
            #[cfg(feature = "multi_template")]
            ast::Stmt::Import(node) => { self.expr(&node.expr); self.target(&node.name); }
            #[cfg(feature = "multi_template")]
            ast::Stmt::FromImport(node) => {
                self.expr(&node.expr);
                for (name, alias) in &node.names { self.target(alias.as_ref().unwrap_or(name)); }
            }
            #[cfg(feature = "macros")]
            ast::Stmt::Macro(node) => self.store(node.name),
            #[cfg(feature = "macros")]
            ast::Stmt::CallBlock(node) => self.call(&node.call),
            #[cfg(feature = "loop_controls")]
            ast::Stmt::Continue(_) | ast::Stmt::Break(_) => {}
            ast::Stmt::Do(node) => self.call(&node.call),
        }
    }
}

// Jinja detects the special `self` parameter across nested scopes before its
// frame-symbol pass, but does not descend into blocks. Unlike frame tracking,
// declarations encountered by this visitor suppress later reads globally.
fn scan_self<'a>(symbols: &mut Symbols<'a>, node: &ast::Stmt<'a>) {
    let mut visit = |nodes: &[ast::Stmt<'a>]| {
        for node in nodes { scan_self(symbols, node); }
    };
    match node {
        ast::Stmt::Template(node) => visit(&node.children),
        ast::Stmt::EmitExpr(node) => symbols.expr(&node.expr),
        ast::Stmt::EmitRaw(_) => {}
        ast::Stmt::ForLoop(node) => {
            symbols.target(&node.target);
            symbols.expr(&node.iter);
            for child in &node.body { scan_self(symbols, child); }
            for child in &node.else_body { scan_self(symbols, child); }
            if let Some(expr) = &node.filter_expr { symbols.expr(expr); }
        }
        ast::Stmt::IfCond(node) => {
            symbols.expr(&node.expr);
            for child in &node.true_body { scan_self(symbols, child); }
            for child in &node.false_body { scan_self(symbols, child); }
        }
        ast::Stmt::WithBlock(node) => {
            for (target, _) in &node.assignments { symbols.target(target); }
            for (_, value) in &node.assignments { symbols.expr(value); }
            for child in &node.body { scan_self(symbols, child); }
        }
        ast::Stmt::Set(node) => { symbols.target(&node.target); symbols.expr(&node.expr); }
        ast::Stmt::SetBlock(node) => {
            symbols.target(&node.target);
            if let Some(filter) = &node.filter { symbols.expr(filter); }
            for child in &node.body { scan_self(symbols, child); }
        }
        ast::Stmt::AutoEscape(node) => {
            symbols.expr(&node.enabled);
            for child in &node.body { scan_self(symbols, child); }
        }
        ast::Stmt::FilterBlock(node) => {
            for child in &node.body { scan_self(symbols, child); }
            symbols.expr(&node.filter);
        }
        #[cfg(feature = "multi_template")]
        ast::Stmt::Block(_) => {}
        #[cfg(feature = "multi_template")]
        ast::Stmt::Extends(node) => symbols.expr(&node.name),
        #[cfg(feature = "multi_template")]
        ast::Stmt::Include(node) => symbols.expr(&node.name),
        #[cfg(feature = "multi_template")]
        ast::Stmt::Import(node) => symbols.expr(&node.expr),
        #[cfg(feature = "multi_template")]
        ast::Stmt::FromImport(node) => symbols.expr(&node.expr),
        #[cfg(feature = "macros")]
        ast::Stmt::Macro(node) => {
            for arg in &node.args { symbols.target(arg); }
            for default in &node.defaults { symbols.expr(default); }
            for child in &node.body { scan_self(symbols, child); }
        }
        #[cfg(feature = "macros")]
        ast::Stmt::CallBlock(node) => {
            symbols.call(&node.call);
            for arg in &node.macro_decl.args { symbols.target(arg); }
            for default in &node.macro_decl.defaults { symbols.expr(default); }
            for child in &node.macro_decl.body { scan_self(symbols, child); }
        }
        #[cfg(feature = "loop_controls")]
        ast::Stmt::Continue(_) | ast::Stmt::Break(_) => {}
        ast::Stmt::Do(node) => symbols.call(&node.call),
    }
}

/// Plan ordered root-frame loads without performing any lookup.
pub fn root_symbol_loads<'a>(template: &ast::Stmt<'a>) -> Vec<RootSymbol<'a>> {
    let mut self_scan = Symbols::default();
    scan_self(&mut self_scan, template);
    let mut symbols = Symbols::default();
    if let Some(entry) = self_scan.entries.iter().find(|entry| entry.name == "self" && entry.load == RootLoadKind::Resolve) {
        symbols.entries.push(RootSymbol { name: entry.name, load: RootLoadKind::SelfReference });
        symbols.stores.insert(entry.name);
    }
    symbols.stmt(template);
    // Jinja initializes the special template reference first and batches
    // missing locals after all resolves, preserving insertion order per kind.
    symbols.entries.sort_by_key(|entry| match entry.load {
        RootLoadKind::SelfReference => 0,
        RootLoadKind::Resolve => 1,
        RootLoadKind::Missing => 2,
    });
    symbols.entries
}

#[cfg(test)]
mod tests {
    use super::{root_symbol_loads, RootLoadKind};
    use crate::compiler::parser::parse;

    #[test]
    fn root_plan_preserves_jinja_order_and_frame_boundaries() {
        use RootLoadKind::{Missing as M, Resolve as R, SelfReference as S};
        let cases: &[(&str, &[(&str, RootLoadKind)])] = &[
            ("{{ a }}{{ b }}{{ a }}", &[("a", R), ("b", R)]),
            ("{% set a,b = pair %}{{a}}{{b}}", &[("pair", R), ("a", M), ("b", M)]),
            ("{% set a=1 %}{% if cond %}{% set a=2 %}{% endif %}{{a}}", &[("cond", R), ("a", M)]),
            ("{% if flag %}{% set a=x %}{% else %}{{y}}{% endif %}{{a}}", &[("flag", R), ("x", R), ("a", R), ("y", R)]),
            ("{% for x in values(offset + threshold) if x > threshold %}{{body}}{% endfor %}{{after}}", &[("values", R), ("offset", R), ("threshold", R), ("after", R)]),
            ("{% with x=left %}{{inside}}{% endwith %}{{after}}", &[("left", R), ("after", R)]),
            ("{% autoescape mode %}{{inside}}{% endautoescape %}{{after}}", &[("after", R)]),
            ("{% filter replace(old, new) %}{{inside}}{% endfilter %}{{after}}", &[("old", R), ("new", R), ("after", R)]),
            ("{% set ns.x = value %}", &[("value", R), ("ns", R)]),
            ("{{ values(*[offset], key=threshold) }}", &[("values", R), ("threshold", R), ("offset", R)]),
            ("{{ array[start:stop:step] }}", &[("array", R), ("start", R), ("stop", R), ("step", R)]),
            ("{% for x in xs %}{{self}}{% endfor %}", &[("self", S), ("xs", R)]),
        ];
        for (source, expected) in cases {
            let template = parse(source, "root-symbol-test", Default::default(), Default::default()).unwrap();
            let actual: Vec<_> = root_symbol_loads(&template).into_iter().map(|entry| (entry.name, entry.load)).collect();
            assert_eq!(&actual, expected, "{source}");
        }
    }

    #[cfg(feature = "multi_template")]
    #[test]
    fn blocks_do_not_request_root_self_but_includes_resolve_their_name() {
        use RootLoadKind::Resolve as R;
        let source = "{% block content %}{{self}}{% endblock %}{% include partial %}";
        let template = parse(source, "root-symbol-test", Default::default(), Default::default()).unwrap();
        let actual: Vec<_> = root_symbol_loads(&template).into_iter().map(|entry| (entry.name, entry.load)).collect();
        assert_eq!(actual, [("partial", R)]);
    }

    #[test]
    fn opt_in_prologue_uses_initial_binding_after_callback_mutation() {
        use crate::value::{Object, Value};
        use std::sync::{Arc, Mutex};

        #[derive(Debug)]
        struct Root(Arc<Mutex<String>>);
        impl Object for Root {
            fn get_value(self: &Arc<Self>, key: &Value) -> Option<Value> {
                (key.as_str() == Some("value")).then(|| Value::from(self.0.lock().unwrap().clone()))
            }
        }

        let value = Arc::new(Mutex::new("old".to_string()));
        let changed = value.clone();
        let mut env = crate::Environment::new();
        env.set_runtime_root_missing(|_, _| Ok(Value::UNDEFINED));
        env.add_function("mutate", move || { *changed.lock().unwrap() = "new".to_string(); "" });
        let source = "{{mutate()}}{{value}}";
        assert_eq!(env.template_from_str(source).unwrap().render(Value::from_object(Root(value))).unwrap(), "old");
    }

    #[test]
    fn error_observer_sees_live_root_bindings_before_state_drops() {
        use crate::value::Value;
        use crate::{Error, ErrorKind};
        use std::sync::{Arc, Mutex};

        let observed = Arc::new(Mutex::new(Vec::new()));
        let output = observed.clone();
        let mut env = crate::Environment::new();
        env.set_runtime_root_missing(|_, _| Ok(Value::UNDEFINED));
        env.set_runtime_error_observer(move |state, error| {
            let value = state.error_frame_bindings().into_iter()
                .find(|(name, _)| name == "value").map(|(_, value)| value.to_string());
            output.lock().unwrap().push((value, error.line()));
        });
        env.add_function("fail", || -> Result<String, Error> { Err(Error::new(ErrorKind::InvalidOperation, "failure")) });
        let template = env.template_from_str("\n{{fail()}}{{value}}").unwrap();
        let error = template.render(crate::context!(value => "captured")).unwrap_err();
        assert_eq!(error.kind(), ErrorKind::InvalidOperation);
        assert_eq!(*observed.lock().unwrap(), [(Some("captured".to_string()), Some(2))]);
        observed.lock().unwrap().clear();
        env.template_from_str("ok").unwrap().render(()).unwrap();
        assert!(observed.lock().unwrap().is_empty());
    }
}
